        "query": "-- Read all three batch files
CREATE OR REPLACE TEMPORARY VIEW batch1 USING CSV OPTIONS (path '/tmp/mlpab8061c6/batch_1.csv', header 'true', inferSchema 'true');

CREATE OR REPLACE TEMPORARY VIEW batch2 USING CSV OPTIONS (path '/tmp/mlpab8061c6/batch_2.csv', header 'true', inferSchema 'true');

CREATE OR REPLACE TEMPORARY VIEW batch3 USING CSV OPTIONS (path '/tmp/mlpab8061c6/batch_3.csv', header 'true', inferSchema 'true');

-- Union all batches
CREATE OR REPLACE TEMPORARY VIEW all_batches AS
SELECT * FROM batch1
UNION ALL
SELECT * FROM batch2
UNION ALL
SELECT * FROM batch3;

-- Deduplicate: keep only the latest row per row_id
CREATE OR REPLACE TEMPORARY VIEW dedup_accounts AS
WITH ranked AS (
  SELECT *,
         ROW_NUMBER() OVER (PARTITION BY row_id ORDER BY updated_at DESC) as rn
  FROM all_batches
)
SELECT row_id, status, balance, updated_at
FROM ranked
WHERE rn = 1;

-- Create the final table in Unity Catalog
CREATE OR REPLACE TABLE workspace.mlpab8061c6.accounts9ad208
AS SELECT * FROM dedup_accounts;

-- Create online table for low-latency access
CREATE ONLINE TABLE workspace.mlpab8061c6.accounts9ad208_online
SOURCE TABLE workspace.mlpab8061c6.accounts9ad208;"
      }
